data = json.load(open(SRC, encoding="utf-8"))
assert len(data) == len(ZH), (len(data), len(ZH))
out = []
for item, zh in zip(data, ZH):
    out.append({"k": item["k"], "zh": zh})

os.makedirs(os.path.dirname(DST), exist_ok=True)
with open(DST, "w", encoding="utf-8") as f:
    json.dump(out, f, ensure_ascii=False, indent=1)
    f.write("\n")

# verify
chk = json.load(open(DST, encoding="utf-8"))
assert len(chk) == len(data)
assert [x["k"] for x in chk] == [x["k"] for x in data]
assert all(isinstance(x["zh"], str) and x["zh"].strip() for x in chk)
print("OK", len(chk), "segments ->", DST)
print("first key", chk[0]["k"], "| chars", sum(len(x["zh"]) for x in chk))
print("greek[0][:50]:", data[0]["g"][:50])
print("zh[0]:", chk[0]["zh"])
